CREATE TABLE public.dimensions (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    dimension_value double precision NOT NULL,
    id uuid NOT NULL,
    product_id uuid,
    description character varying(255),
    dimension_type character varying(255),
    unit_of_measure character varying(255),
    CONSTRAINT dimensions_dimension_type_check CHECK (((dimension_type)::text = ANY (ARRAY[('LENGTH'::character varying)::text, ('WIDTH'::character varying)::text, ('HEIGHT'::character varying)::text, ('WEIGHT'::character varying)::text, ('VOLUME'::character varying)::text, ('AREA'::character varying)::text, ('DIAMETER'::character varying)::text, ('CIRCUMFERENCE'::character varying)::text, ('RADIUS'::character varying)::text, ('TEMPERATURE'::character varying)::text, ('TIME'::character varying)::text, ('SPEED'::character varying)::text, ('PRESSURE'::character varying)::text, ('FORCE'::character varying)::text, ('ENERGY'::character varying)::text, ('POWER'::character varying)::text, ('FREQUENCY'::character varying)::text, ('ANGLE'::character varying)::text, ('DATA_SIZE'::character varying)::text, ('CURRENT'::character varying)::text, ('VOLTAGE'::character varying)::text, ('RESISTANCE'::character varying)::text])))
);

