    qty_on_hand numeric(19,4) NOT NULL,
    standard_cost numeric(19,4),
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    item_cost_id uuid NOT NULL,
    item_id uuid NOT NULL
);

CREATE TABLE public.item_cost_audit (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    new_value numeric(19,4),
    old_value numeric(19,4),
    audit_timestamp timestamp(6) with time zone NOT NULL,
    audit_id uuid NOT NULL,
    item_id uuid NOT NULL,
    actor character varying(255) NOT NULL,
    change_source_id character varying(255) NOT NULL,
    change_source_type character varying(255) NOT NULL,
    cost_type_changed character varying(255) NOT NULL,
    reason_code character varying(255),
    CONSTRAINT item_cost_audit_change_source_type_check CHECK (((change_source_type)::text = ANY (ARRAY[('MANUAL'::character varying)::text, ('PURCHASE_ORDER'::character varying)::text]))),
    CONSTRAINT item_cost_audit_cost_type_changed_check CHECK (((cost_type_changed)::text = ANY (ARRAY[('STANDARD'::character varying)::text, ('LAST'::character varying)::text, ('AVERAGE'::character varying)::text])))
);

CREATE TABLE public.labor_guide_import (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    import_manifest_id uuid NOT NULL,
    source_code character varying(32) NOT NULL,
    source_revision character varying(64) NOT NULL,
    expected_chunk_count integer NOT NULL,
    expected_line_count bigint NOT NULL,
    content_checksum character varying(128) NOT NULL,
    chunks_applied integer DEFAULT 0 NOT NULL,
    lines_applied bigint DEFAULT 0 NOT NULL,
    lines_unmapped bigint DEFAULT 0 NOT NULL,
    status character varying(16) NOT NULL,
    completed_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT ck_lgi_status CHECK (((status)::text = ANY ((ARRAY['APPLYING'::character varying, 'COMPLETE'::character varying, 'INCOMPLETE'::character varying])::text[])))
);

CREATE TABLE public.labor_guide_import_chunk (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
