);

CREATE TABLE public.labor_time_source_policy (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    id uuid NOT NULL,
    time_type character varying(24) NOT NULL,
    source_code character varying(32) NOT NULL,
    precedence integer NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    operation_category character varying(32),
    CONSTRAINT ck_ltsp_operation_category CHECK (((operation_category IS NULL) OR ((operation_category)::text = ANY ((ARRAY['REPAIR'::character varying, 'DIAGNOSTIC'::character varying, 'MAINTENANCE'::character varying, 'TIRE_SERVICE'::character varying])::text[])))),
    CONSTRAINT ck_ltsp_time_type CHECK (((time_type)::text = ANY ((ARRAY['RETAIL_FLAT_RATE'::character varying, 'OEM_WARRANTY'::character varying, 'MANUFACTURER_INSTALL'::character varying, 'DURION_STANDARD'::character varying])::text[])))
);

CREATE TABLE public.location_price_override (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    base_price numeric(19,4) NOT NULL,
    cost numeric(19,4),
    discount_percent numeric(10,4) NOT NULL,
    margin_percent numeric(10,4),
    override_price numeric(19,4) NOT NULL,
    approved_at timestamp(6) with time zone,
    created_at timestamp(6) with time zone NOT NULL,
    rejected_at timestamp(6) with time zone,
    resolved_at timestamp(6) with time zone,
    version bigint,
    approved_by_user_id uuid,
    created_by_user_id uuid NOT NULL,
    id uuid NOT NULL,
    location_id uuid NOT NULL,
    product_id uuid NOT NULL,
    rejected_by uuid,
    status character varying(32) NOT NULL,
    rejection_reason_code character varying(128),
    rejection_notes character varying(1024),
    CONSTRAINT location_price_override_status_check CHECK (((status)::text = ANY (ARRAY[('ACTIVE'::character varying)::text, ('PENDING_APPROVAL'::character varying)::text, ('REJECTED'::character varying)::text, ('INACTIVE'::character varying)::text])))
);

