    updated_at timestamp(6) with time zone NOT NULL,
    version bigint,
    price_book_id uuid NOT NULL,
    scope_id uuid,
    status character varying(16) NOT NULL,
    scope character varying(32) NOT NULL,
    name character varying(255) NOT NULL,
    CONSTRAINT price_book_scope_check CHECK (((scope)::text = ANY (ARRAY[('COMPANY_DEFAULT'::character varying)::text, ('LOCATION'::character varying)::text, ('CUSTOMER_TIER'::character varying)::text]))),
    CONSTRAINT price_book_status_check CHECK (((status)::text = ANY (ARRAY[('ACTIVE'::character varying)::text, ('INACTIVE'::character varying)::text])))
);

CREATE TABLE public.price_book_rule (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    priority integer NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    effective_end_at timestamp(6) with time zone,
    effective_start_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    version bigint,
    created_by_user_id uuid NOT NULL,
    price_book_id uuid NOT NULL,
    rule_id uuid NOT NULL,
    target_id uuid,
    target_type character varying(16) NOT NULL,
    condition_type character varying(32) NOT NULL,
    status character varying(32) NOT NULL,
    condition_value character varying(255),
    pricing_logic text NOT NULL,
    CONSTRAINT price_book_rule_condition_type_check CHECK (((condition_type)::text = ANY (ARRAY[('CUSTOMER_TIER'::character varying)::text, ('LOCATION'::character varying)::text, ('NONE'::character varying)::text]))),
    CONSTRAINT price_book_rule_status_check CHECK (((status)::text = ANY (ARRAY[('ACTIVE'::character varying)::text, ('INACTIVE'::character varying)::text, ('NOT_APPLICABLE_MISSING_BASE'::character varying)::text]))),
    CONSTRAINT price_book_rule_target_type_check CHECK (((target_type)::text = ANY (ARRAY[('SKU'::character varying)::text, ('CATEGORY'::character varying)::text, ('GLOBAL'::character varying)::text])))
);

CREATE TABLE public.processed_events (
