    processed_at timestamp(6) with time zone NOT NULL
);

CREATE TABLE public.product (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    last_state_changed_at timestamp(6) with time zone,
    lifecycle_state_effective_at timestamp(6) with time zone,
    updated_at timestamp(6) with time zone NOT NULL,
    category_id uuid,
    id uuid NOT NULL,
    last_state_changed_by uuid,
    manufacturer_id uuid,
    subcategory_id uuid,
    color character varying(255),
    country_of_origin character varying(255),
    description character varying(255),
    lifecycle_override_reason character varying(255),
    lifecycle_state character varying(255) DEFAULT 'ACTIVE'::character varying NOT NULL,
    long_description character varying(255),
    manufacturer_brand character varying(255),
    manufacturer_name character varying(255),
    manufacturer_part_number character varying(255),
    manufacturer_warranty character varying(255),
    material character varying(255),
    name character varying(255),
    product_code character varying(255),
    product_code_type character varying(255),
    short_description character varying(255),
    sku character varying(255),
    status character varying(255) DEFAULT 'ACTIVE'::character varying NOT NULL,
    type character varying(255),
    unit_of_measure character varying(255),
    upc character varying(255),
    warranty character varying(255),
    tracking_level character varying(16) DEFAULT 'NONE'::character varying NOT NULL,
    tread_design_id uuid,
    attributes text,
    specifications text,
    version bigint DEFAULT 0 NOT NULL,
    tread_design_source character varying(10),
    CONSTRAINT ck_product_tread_design_source_paired CHECK (((tread_design_id IS NULL) = (tread_design_source IS NULL))),
    CONSTRAINT product_lifecycle_state_check CHECK (((lifecycle_state)::text = ANY (ARRAY[('ACTIVE'::character varying)::text, ('INACTIVE'::character varying)::text, ('DISCONTINUED'::character varying)::text]))),
    CONSTRAINT product_product_code_type_check CHECK (((product_code_type)::text = ANY (ARRAY[('UPC'::character varying)::text, ('EAN'::character varying)::text]))),
    CONSTRAINT product_status_check CHECK (((status)::text = ANY (ARRAY[('ACTIVE'::character varying)::text, ('INACTIVE'::character varying)::text]))),
    CONSTRAINT product_tracking_level_check CHECK (((tracking_level)::text = ANY (ARRAY[('NONE'::character varying)::text, ('LOT'::character varying)::text, ('SERIAL'::character varying)::text])))
);

CREATE TABLE public.product_code_duplicate_report (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    code_type character varying(32) NOT NULL,
    code_value character varying(255) NOT NULL,
    product_count integer NOT NULL,
    product_ids text NOT NULL,
    detected_at timestamp(6) with time zone DEFAULT now() NOT NULL
);

COMMENT ON TABLE public.product_code_duplicate_report IS 'EAN/UPC values carried by more than one product at the time the per-type uniqueness constraint was applied (#1232).';

