    precision_scale integer NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    CONSTRAINT product_uom_uom_type_check CHECK (((uom_type)::text = ANY (ARRAY[('BASE'::character varying)::text, ('PURCHASE'::character varying)::text, ('PACK'::character varying)::text, ('OTHER'::character varying)::text])))
);

CREATE TABLE public.service (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    id uuid NOT NULL,
    long_description character varying(255),
    name character varying(255),
    short_description character varying(255),
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    operation_code character varying(64),
    operation_category character varying(32),
    default_labor_hours numeric(5,1),
    CONSTRAINT ck_service_operation_category CHECK (((operation_category IS NULL) OR ((operation_category)::text = ANY ((ARRAY['REPAIR'::character varying, 'DIAGNOSTIC'::character varying, 'MAINTENANCE'::character varying, 'TIRE_SERVICE'::character varying])::text[]))))
);

CREATE TABLE public.service_labor_standard (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    id uuid NOT NULL,
    service_id uuid NOT NULL,
    vehicle_year character varying(16),
    make character varying(64),
    model character varying(64),
    submodel character varying(64),
    engine_code character varying(64),
    aces_vehicle_id bigint,
    labor_hours numeric(5,1) NOT NULL,
    time_type character varying(24) NOT NULL,
    overlap_group character varying(64),
    included_op_codes text[],
    source_code character varying(32) NOT NULL,
    source_revision character varying(64) NOT NULL,
    published_at date,
    import_manifest_id uuid,
    superseded_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    owner_scope character varying(16) DEFAULT 'PLATFORM'::character varying NOT NULL,
    owner_location_id uuid,
    CONSTRAINT ck_sls_owner_scope CHECK ((((owner_scope)::text = ANY ((ARRAY['PLATFORM'::character varying, 'SHOP'::character varying])::text[])) AND ((((owner_scope)::text = 'SHOP'::text) AND (owner_location_id IS NOT NULL)) OR (((owner_scope)::text = 'PLATFORM'::text) AND (owner_location_id IS NULL))))),
    CONSTRAINT ck_sls_time_type CHECK (((time_type)::text = ANY ((ARRAY['RETAIL_FLAT_RATE'::character varying, 'OEM_WARRANTY'::character varying, 'MANUFACTURER_INSTALL'::character varying, 'DURION_STANDARD'::character varying])::text[])))
);

CREATE TABLE public.service_operation_xref (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    id uuid NOT NULL,
    service_id uuid NOT NULL,
    source_code character varying(32) NOT NULL,
    provider_op_code character varying(128) NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL
);

CREATE TABLE public.service_package (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    id uuid NOT NULL,
    package_code character varying(64) NOT NULL,
    name character varying(255) NOT NULL,
    description text,
    owner_scope character varying(16) DEFAULT 'PLATFORM'::character varying NOT NULL,
    owner_location_id uuid,
    fleet_party_id uuid,
    package_labor_hours numeric(5,1),
    active boolean DEFAULT true NOT NULL,
    effective_from date,
    effective_to date,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT ck_svc_pkg_owner_scope CHECK ((((owner_scope)::text = ANY ((ARRAY['PLATFORM'::character varying, 'SHOP'::character varying])::text[])) AND ((((owner_scope)::text = 'SHOP'::text) AND (owner_location_id IS NOT NULL)) OR (((owner_scope)::text = 'PLATFORM'::text) AND (owner_location_id IS NULL))))),
    CONSTRAINT ck_svc_pkg_window CHECK (((effective_to IS NULL) OR (effective_from IS NULL) OR (effective_to >= effective_from)))
);

CREATE TABLE public.service_package_member (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
