    effective_from date NOT NULL,
    source_document_id character varying(255),
    source_document_date date,
    import_manifest_id uuid NOT NULL,
    fetched_at timestamp(6) with time zone NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    CONSTRAINT ck_supplier_price_entry_match_method CHECK (((match_method)::text = ANY ((ARRAY['EAN'::character varying, 'UPC_XREFERENCE'::character varying])::text[])))
);

CREATE TABLE public.supplier_price_import (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    import_manifest_id uuid NOT NULL,
    vendor_profile_id uuid NOT NULL,
    supplier_ref character varying(100),
    chunks_applied integer DEFAULT 0 NOT NULL,
    lines_applied integer DEFAULT 0 NOT NULL,
    expected_chunk_count integer,
    expected_line_count integer,
    content_checksum character varying(64),
    status character varying(32) NOT NULL,
    completed_at timestamp(6) with time zone,
    updated_at timestamp(6) with time zone NOT NULL,
    CONSTRAINT ck_supplier_price_import_status CHECK (((status)::text = ANY ((ARRAY['APPLYING'::character varying, 'COMPLETE'::character varying, 'INCOMPLETE'::character varying])::text[])))
);

CREATE TABLE public.supplier_price_import_chunk (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    id uuid NOT NULL,
    import_manifest_id uuid NOT NULL,
    chunk_sequence integer NOT NULL,
    lines_applied integer NOT NULL,
    applied_at timestamp(6) with time zone NOT NULL
);

CREATE TABLE public.tread_design (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    id uuid NOT NULL,
    vendor_profile_id uuid NOT NULL,
    supplier_ref character varying(100) NOT NULL,
    vendor_variant_id character varying(100) NOT NULL,
    brand character varying(200),
    tread_design character varying(200),
    tread_design_2 character varying(200),
    product_name character varying(300),
    vehicle_type character varying(100),
    seasonality character varying(100),
    content_hash character varying(64) NOT NULL,
    has_unresolved_images boolean NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    match_state character varying(20) NOT NULL,
    match_state_at timestamp(6) with time zone NOT NULL,
    resolved_by character varying(200),
    resolution_note text,
    defer_until timestamp(6) with time zone
);

CREATE TABLE public.tread_design_image (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    id uuid NOT NULL,
    tread_design_id uuid NOT NULL,
    image_type character varying(100),
    image_id bigint,
    content_hash character varying(64),
    source_uri character varying(1000),
    unresolved boolean NOT NULL
);

CREATE TABLE public.tread_design_match_candidate (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    id uuid NOT NULL,
    tread_design_id uuid NOT NULL,
    product_id uuid NOT NULL,
    score numeric(5,4) NOT NULL,
    tier character varying(20) NOT NULL,
    created_at timestamp(6) with time zone NOT NULL
);

CREATE TABLE public.tread_design_text (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    id uuid NOT NULL,
    tread_design_id uuid NOT NULL,
    language_code character varying(16) NOT NULL,
